import { INSTRUCTION_VARIABLES, PIPELINE_EVENT_TYPES, type Policy } from "@outstaff/policy";
import { conditionLines } from "./reference-parts.js";

const code = (s: string) => `\`${s}\``;
const cell = (s: string) => s.replaceAll("|", "\\|");

const INTRO = [
  "---",
  "title: Pipeline policies",
  "description: The built-in policies of the event pipeline, in evaluation order, with what each listens to, when it matches, what it decides and the instruction it gives.",
  "---",
  "",
  "<!-- Generated by `pnpm --filter @outstaff/office run docs:pipeline`. Do not edit by hand. -->",
  "",
  "These are the built-in policies the office runs, in evaluation order ([decision 0018](/decisions/0018-pipeline-only/)). Each is a module in `packages/office/src/pipeline/policies/`, and this page is generated from them. Every policy that listens to an event receives it and proposes; the aggregation layer turns the proposals into the decisions. [What outstaff does on its own](/concepts/automation/) explains the events and the decisions, and [Writing a policy](/guides/writing-a-policy/) how to add a policy of your own.",
  "",
  "A team changes a policy under [`pipeline.policies.<id>`](/reference/team-yaml/#pipelinepolicies) in team.yaml: `enabled: false` turns it off (it stays in the trace), `instruction` replaces the instruction of a wake or the note of an act, and `when` narrows it, so both its own condition and the team's must hold. Policies of the team's own, under [`policies.custom`](/reference/team-yaml/#policiescustom), run after these.",
];

/** One row of the overview: the policy, what it listens to and what it decides. */
const row = (p: Policy): string =>
  `| [${code(p.id)}](#${p.id}) | ${p.on.map(code).join(", ")} | ${cell(p.decides ?? "")} |`;

function switchLines(p: Policy, switches: Readonly<Record<string, string>>): string[] {
  const path = switches[p.id];
  return path ? ["", `On only while ${code(`policies.${path}`)} is on.`] : [];
}

const whenLines = (p: Policy): string[] =>
  p.when ? ["", "When:", "", ...conditionLines(p.when)] : ["", "When: always."];

const NO_NOTE = "Note posted with the change: none";

/** For a policy that acts: that it posts no note, when it does not; an act-only policy's team can still add one. */
function noNoteLines(p: Policy, wakes: boolean): string[] {
  if (!(p.decides ?? "").startsWith("act for")) {
    return [];
  }

  if (wakes) {
    return ["", `${NO_NOTE}; the instruction is the wake's.`];
  }

  return p.instruction
    ? []
    : [
        "",
        `${NO_NOTE}, since the ticket shows the change. A team can add one with ${code(`pipeline.policies.${p.id}.instruction`)}.`,
      ];
}

function instructionLines(p: Policy): string[] {
  const wakes = (p.decides ?? "").includes("wake");
  const label = wakes ? "Instruction:" : "Note posted with the change:";
  const text = p.instruction ? ["", label, "", "```text", p.instruction, "```"] : [];
  return [...text, ...noNoteLines(p, wakes)];
}

function policySection(p: Policy, switches: Readonly<Record<string, string>>): string[] {
  return [
    "",
    `### ${p.id}`,
    "",
    p.summary,
    "",
    `Listens to ${p.on.map(code).join(", ")}. Decides: ${p.decides}.`,
    ...switchLines(p, switches),
    ...whenLines(p),
    ...instructionLines(p),
  ];
}

/** Markdown for the pipeline policies reference page, generated from the built-in policy modules. */
export function renderPolicyReference(
  policies: readonly Policy[],
  switches: Readonly<Record<string, string>>,
): string {
  return [
    ...INTRO,
    "",
    "## Overview",
    "",
    "| Policy | Listens to | Decides |",
    "| --- | --- | --- |",
    ...policies.map(row),
    "",
    "## Policies",
    ...policies.flatMap((p) => policySection(p, switches)),
    "",
    "## Events",
    "",
    "Every event the pipeline decides on. A policy's `on` lists some of them.",
    "",
    ...PIPELINE_EVENT_TYPES.map((t) => `- ${code(t)}`),
    "",
    "## Instruction variables",
    "",
    "An instruction or note may use these placeholders, written `{{name}}`. One the event does not have is empty, and an unknown name in `pipeline.policies.<id>.instruction` keeps the default instruction, with a warning in the office log.",
    "",
    ...INSTRUCTION_VARIABLES.map((v) => `- ${code(v)}`),
    "",
  ].join("\n");
}
